import{APP_VERSION,TABLES}from'./config.js';import{rows,dirty,tombstone,setting,setSetting,clearAll,putRow}from'./db.js';import{signIn,signUp,signOut,currentSession}from'./auth.js';import{syncAll}from'./sync.js';import{concertMetrics,minutesBetween}from'./calculations.js';import{makeDocx,makeTableDocx,makeAttendanceDocx,makeProgramDocx,downloadBlob}from'./docx.js';
const $=s=>document.querySelector(s), content=$('#content');let view='dashboard',ctx={institution:null,ensemble:null},deferredInstall=null;
const short=t=>t.replace('conductix_','');const T=n=>'conductix_'+n;const NAV=[['dashboard','Panel general'],['institutions','Instituciones'],['ensembles','Agrupaciones'],['categories','Secciones'],['academic_levels','Niveles o grupos'],['members','Integrantes'],['attendance','Asistencia'],['agenda','Agenda y planificación'],['repertoire','Repertorio'],['concert_programs','Programas'],['reports','Exportación'],['settings','Configuración']];
function toast(m){const e=$('#toast');e.textContent=m;e.classList.remove('hidden');clearTimeout(toast.t);toast.t=setTimeout(()=>e.classList.add('hidden'),2600)}function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function fmtDate(s){if(!s)return'';return new Intl.DateTimeFormat('es-ES',{dateStyle:'medium',timeZone:'UTC'}).format(new Date(s+'T12:00:00Z'))}function downloadText(s,n,type='application/json'){downloadBlob(new Blob([s],{type}),n)}
async function data(n,filter=null){let a=await rows(T(n));if(filter)a=a.filter(filter);return a;}async function byId(n,id){if(!id)return null;return(await data(n)).find(x=>x.id===id)||null;}function setPage(title,sub='',actions=''){$('#pageTitle').textContent=title;$('#pageSubtitle').textContent=sub;$('#pageActions').innerHTML=actions;}
function nav(){const e=$('#nav');e.innerHTML=NAV.map(([k,l])=>`<button data-view="${k}" class="${view===k?'active':''}">${l}</button>`).join('');e.querySelectorAll('button').forEach(b=>b.onclick=()=>show(b.dataset.view));}
async function refreshContext(){const inst=await data('institutions'),ens=await data('ensembles');const iv=$('#institutionContext'),ev=$('#ensembleContext');iv.innerHTML='<option value="">Todas las instituciones</option>'+inst.filter(x=>x.active!==false).map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('');iv.value=ctx.institution||'';const e2=ens.filter(x=>!ctx.institution||x.institution_id===ctx.institution);ev.innerHTML='<option value="">Todas las agrupaciones</option>'+e2.filter(x=>x.active!==false).map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('');if(ctx.ensemble&&!e2.some(x=>x.id===ctx.ensemble))ctx.ensemble=null;ev.value=ctx.ensemble||'';await setSetting('context',ctx);}
function fieldsHtml(fields,row={}){return fields.map(f=>{let v=row[f.name]??f.default??'';let input;if(f.type==='select'){const opts=(typeof f.options==='function'?f.options():f.options)||[];input=`<select name="${f.name}" ${f.required?'required':''}><option value="">${f.blank||'—'}</option>${opts.map(o=>`<option value="${esc(o.value)}" ${String(v)===String(o.value)?'selected':''}>${esc(o.label)}</option>`).join('')}</select>`;}else if(f.type==='textarea')input=`<textarea name="${f.name}" ${f.required?'required':''}>${esc(v)}</textarea>`;else if(f.type==='checkbox')input=`<input name="${f.name}" type="checkbox" ${v?'checked':''}>`;else input=`<input name="${f.name}" type="${f.type||'text'}" value="${esc(v)}" ${f.required?'required':''}>`;return `<label class="${f.full?'full':''}">${f.label}${input}</label>`}).join('');}
function openForm(title,fields,row,onSave){$('#modalTitle').textContent=title;const form=$('#modalForm');form.innerHTML=fieldsHtml(fields,row)+`<div class="form-actions"><button type="button" class="secondary" data-cancel>Cancelar</button><button>Guardar</button></div>`;$('#modal').classList.remove('hidden');form.querySelector('[data-cancel]').onclick=closeModal;form.onsubmit=async e=>{e.preventDefault();const fd=new FormData(form),out={...row};for(const f of fields){out[f.name]=f.type==='checkbox'?form.elements[f.name].checked:fd.get(f.name);if(f.type==='number'&&out[f.name]!=='')out[f.name]=Number(out[f.name]);if((f.type==='date'||f.type==='time')&&out[f.name]==='')out[f.name]=null;if(f.type==='select'&&f.nullable&&out[f.name]==='')out[f.name]=null;}try{await onSave(out);closeModal();await render();toast('Guardado');}catch(err){toast(err.message)}};}
function closeModal(){$('#modal').classList.add('hidden');$('#modalForm').onsubmit=null;}$('#modalClose').onclick=closeModal;$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))closeModal()});
function askConfirm(message){return new Promise(resolve=>{const modal=$('#modal'),form=$('#modalForm');$('#modalTitle').textContent='Confirmar';form.innerHTML=`<div class="full"><p>${esc(message)}</p></div><div class="form-actions"><button type="button" class="secondary" data-no>Cancelar</button><button type="button" class="danger" data-yes>Quitar</button></div>`;modal.classList.remove('hidden');const done=v=>{closeModal();resolve(v)};form.querySelector('[data-no]').onclick=()=>done(false);form.querySelector('[data-yes]').onclick=()=>done(true);});}
async function confirmDelete(table,row,label){if(!await askConfirm(`¿Quitar ${label}?`))return;await tombstone(table,row);await render();}
function genericTable(cols,rowsData,actions=true){if(!rowsData.length)return'<div class="empty">No hay registros.</div>';return `<div class="table-wrap"><table><thead><tr>${cols.map(c=>`<th>${c.label}</th>`).join('')}${actions?'<th>Acciones</th>':''}</tr></thead><tbody>${rowsData.map(r=>`<tr>${cols.map(c=>`<td>${c.render?c.render(r):esc(r[c.key]??'')}</td>`).join('')}${actions?`<td><div class="actions"><button class="small secondary" data-edit="${r.id}">Editar</button><button class="small danger" data-del="${r.id}">Quitar</button></div></td>`:''}</tr>`).join('')}</tbody></table></div>`;}
async function wireCrud(table,arr,fields,label){content.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>openForm(`Editar ${label}`,fields,arr.find(x=>x.id===b.dataset.edit),r=>dirty(table,r)));content.querySelectorAll('[data-del]').forEach(b=>b.onclick=()=>{const r=arr.find(x=>x.id===b.dataset.del);confirmDelete(table,r,label)});$('#pageActions [data-new]')?.addEventListener('click',()=>openForm(`Nueva/o ${label}`,fields,{id:crypto.randomUUID(),created_at:new Date().toISOString()},r=>dirty(table,r)));}
const ENSEMBLE_TYPES=['Coro','Coro de voces claras','Coro infantil','Orquesta','Orquesta de cuerdas','Banda','Ensamble de maderas','Ensamble de metales','Ensamble de cuerdas','Grupo instrumental','Otro'];
