function fullName(m){return[m?.first_name,m?.last_name].filter(Boolean).join(' ').trim()}
function todayIso(){return new Date().toISOString().slice(0,10)}
function timeShort(v){return String(v||'').slice(0,5)}
function formatHoursValue(value){return Number(value||0).toFixed(2)}
function safeArray(v){return Array.isArray(v)?v:[]}
function uniq(values){return[...new Set(values.filter(Boolean))]}
function openCustomModal(title,html,onMount){$('#modalTitle').textContent=title;const form=$('#modalForm');form.innerHTML=html;$('#modal').classList.remove('hidden');form.onsubmit=e=>e.preventDefault();onMount?.(form);return form}
async function toggleActive(table,row){await dirty(T(table),{...row,active:row.active===false});await render()}
async function reorderRows(table,arr,id,direction){const ordered=[...arr].sort((a,b)=>Number(a.display_order||0)-Number(b.display_order||0)||String(a.name||'').localeCompare(String(b.name||''),'es'));const idx=ordered.findIndex(x=>x.id===id),target=idx+direction;if(idx<0||target<0||target>=ordered.length)return;[ordered[idx],ordered[target]]=[ordered[target],ordered[idx]];for(let i=0;i<ordered.length;i++)await dirty(T(table),{...ordered[i],display_order:i+1});await render()}
async function setContext(institutionId=null,ensembleId=null){ctx.institution=institutionId||null;ctx.ensemble=ensembleId||null;if(ctx.ensemble){const e=await byId('ensembles',ctx.ensemble);if(e)ctx.institution=e.institution_id;}await setSetting('context',ctx);await refreshContext();await render()}
function opt(value,label,current){return`<option value="${esc(value)}" ${String(value)===String(current)?'selected':''}>${esc(label)}</option>`}
function checkList(name,items,selected=[]){const set=new Set(selected);return`<div class="check-list">${items.map(x=>`<label class="check-item"><input type="checkbox" name="${name}" value="${esc(x.value)}" ${set.has(x.value)?'checked':''}><span>${esc(x.label)}</span></label>`).join('')}</div>`}
function selectedChecks(form,name){return[...form.querySelectorAll(`input[name="${name}"]:checked`)].map(x=>x.value)}
function normalizeName(v){return String(v||'').trim().toLocaleLowerCase('es')}
async function ensureParitySettings(){if(await setting('customCategoryTemplates',null)===null)await setSetting('customCategoryTemplates',LEGACY_CUSTOM_CATEGORY_TEMPLATES);}
async function saveFullBackup(){const out={format:'conductix-v2',kind:'full-backup',exportedAt:new Date().toISOString(),settings:{customCategoryTemplates:await setting('customCategoryTemplates',{}),theme:await setting('theme','light')},tables:{}};for(const t of TABLES)out.tables[short(t)]=(await rows(t,{deleted:true})).map(x=>Object.fromEntries(Object.entries(x).filter(([k])=>!k.startsWith('_'))));downloadText(JSON.stringify(out,null,2),`Conductix_respaldo_${todayIso()}.json`);}
async function restoreFullBackupObject(obj){if(obj?.format!=='conductix-v2')throw new Error('El archivo no es un respaldo Conductix 2.');if(!await askConfirm('La restauración sustituirá los datos locales actuales por el respaldo seleccionado. ¿Continuar?'))return false;await clearAll();for(const[t,a]of Object.entries(obj.tables||{})){const table=T(t);if(!TABLES.includes(table))continue;for(const r of a)await dirty(table,{...r,id:r.id||crypto.randomUUID()});}if(obj.settings?.customCategoryTemplates)await setSetting('customCategoryTemplates',obj.settings.customCategoryTemplates);if(obj.settings?.theme)await setSetting('theme',obj.settings.theme);await refreshContext();return true;}
function planningTemplateObject(){return{schema_version:1,concerts:[{external_id:'fin_de_curso_2026',ensemble:'Coro ESO',title:'Fin de curso',date:'2026-06-03',time:'',location:'',regular_weekdays:[1],regular_start_time:'10:40',regular_end_time:'11:30',notes:'',extras:[{date:'2026-04-18',start_time:'19:00',end_time:'21:00',notes:''}]}],blocks:[{date:'2026-05-12',type:'full_day',ensemble:'',notes:''}]};}
async function importPlanningObject(obj){
 if(!obj||typeof obj!=='object'||Array.isArray(obj))throw new Error('El archivo de planificación debe contener un objeto JSON.');if(Number(obj.schema_version??1)!==1)throw new Error('Versión de esquema JSON no compatible.');
 const concerts=Array.isArray(obj.concerts)?obj.concerts:null,blocks=Array.isArray(obj.blocks)?obj.blocks:null;if(!concerts||!blocks)throw new Error('El JSON debe contener listas concerts y blocks.');
 const ens=await data('ensembles'),byName=new Map(ens.map(e=>[normalizeName(e.name),e]));const resolve=(item,required=true)=>{let e=item?.ensemble_id?ens.find(x=>x.id===String(item.ensemble_id)):null;if(!e&&item?.ensemble)e=byName.get(normalizeName(item.ensemble));if(!e&&required&&ctx.ensemble)e=ens.find(x=>x.id===ctx.ensemble);if(required&&!e)throw new Error(`No se pudo resolver la agrupación para “${item?.title||item?.ensemble||'elemento'}”.`);return e||null};
 let nc=0,ne=0,nb=0;for(const c of concerts){for(const f of ['title','date','regular_weekdays','regular_start_time','regular_end_time'])if(!(f in c))throw new Error(`Falta el campo ${f} en un concierto.`);if(!Array.isArray(c.extras??[]))throw new Error('extras debe ser una lista.');const ensemble=resolve(c,true),id=crypto.randomUUID(),weekdays=Array.isArray(c.regular_weekdays)?c.regular_weekdays.map(Number):String(c.regular_weekdays).split(',').map(x=>Number(x.trim())).filter(Number.isFinite);await dirty(T('planned_concerts'),{id,ensemble_id:ensemble.id,title:String(c.title).trim(),concert_date:String(c.date).trim(),start_time:String(c.time||'').trim()||null,location:String(c.location||'').trim(),regular_weekdays:weekdays.join(','),regular_start_time:String(c.regular_start_time).trim(),regular_end_time:String(c.regular_end_time).trim(),weekly_schedule:{weekdays,start:String(c.regular_start_time).trim(),end:String(c.regular_end_time).trim()},notes:String(c.notes||''),created_at:new Date().toISOString()});nc++;for(const ex of c.extras??[]){for(const f of ['date','start_time','end_time'])if(!(f in ex))throw new Error(`Falta ${f} en un ensayo extra.`);await dirty(T('extra_rehearsals'),{id:crypto.randomUUID(),concert_id:id,ensemble_id:ensemble.id,rehearsal_date:String(ex.date).trim(),start_time:String(ex.start_time).trim(),end_time:String(ex.end_time).trim(),duration_minutes:minutesBetween(ex.start_time,ex.end_time),notes:String(ex.notes||''),created_at:new Date().toISOString()});ne++;}}
 for(const b of blocks){for(const f of ['date','type'])if(!(f in b))throw new Error(`Falta ${f} en un bloqueo.`);const ensemble=resolve(b,false);await dirty(T('planning_blocks'),{id:crypto.randomUUID(),ensemble_id:ensemble?.id||null,block_date:String(b.date).trim(),block_type:String(b.type).trim(),block_scope:ensemble?'ensemble':'global',notes:String(b.notes||''),created_at:new Date().toISOString()});nb++;}return{concerts:nc,extras:ne,blocks:nb};}

async function dashboard(){
 setPage('Panel general','Resumen operativo y próximos compromisos');
 const [inst,ens,mem,concerts,events]=await Promise.all(['institutions','ensembles','members','planned_concerts','events'].map(n=>data(n)));
 const upcoming=[...concerts.map(x=>({...x,kind:'Concierto',date:x.concert_date})),...events.map(x=>({...x,kind:x.event_type||'Evento',date:x.event_date}))].filter(x=>x.date>=todayIso()).sort((a,b)=>a.date.localeCompare(b.date)).slice(0,8);
 const instName=inst.find(x=>x.id===ctx.institution)?.name||'ninguna',ensName=ens.find(x=>x.id===ctx.ensemble)?.name||'ninguna';
 content.innerHTML=`<div class="cards dashboard-six"><div class="card"><span class="muted">Instituciones</span><div class="value">${inst.length}</div></div><div class="card"><span class="muted">Instituciones activas</span><div class="value">${inst.filter(x=>x.active!==false).length}</div></div><div class="card"><span class="muted">Agrupaciones</span><div class="value">${ens.length}</div></div><div class="card"><span class="muted">Agrupaciones activas</span><div class="value">${ens.filter(x=>x.active!==false).length}</div></div><div class="card"><span class="muted">Integrantes activos</span><div class="value">${mem.filter(x=>x.active!==false).length}</div></div><div class="card"><span class="muted">Conciertos planificados</span><div class="value">${concerts.length}</div></div></div><div class="grid2" style="margin-top:16px"><div class="panel"><h2>Contexto actual</h2><p>Institución activa: <strong>${esc(instName)}</strong></p><p>Agrupación activa: <strong>${esc(ensName)}</strong></p></div><div class="panel"><h2>Próximos compromisos</h2>${upcoming.length?upcoming.map(x=>`<div class="program-item"><span class="pill">${esc(x.kind)}</span><div><strong>${esc(x.title)}</strong><div class="muted">${fmtDate(x.date)} · ${esc(x.location||'')}</div></div></div>`).join(''):'<div class="empty">No hay compromisos próximos.</div>'}</div></div>`;
}
