 content.innerHTML=`<div class="panel"><div class="toolbar"><label class="inline-field">Buscar <input id="institutionSearch" placeholder="Nombre o notas"></label><label class="inline-check"><input id="institutionInactive" type="checkbox" checked> Mostrar inactivas</label></div><div class="table-wrap"><table><thead><tr><th>Institución</th><th>Estado</th><th>Agrupaciones</th><th>Notas</th><th>Acciones</th></tr></thead><tbody>${rowsHtml||'<tr><td colspan="5" class="empty">No hay instituciones.</td></tr>'}</tbody></table></div><p id="institutionCount" class="muted"></p></div>`;
 const fields=[{name:'name',label:'Nombre',required:true},{name:'active',label:'Activa',type:'checkbox',default:true},{name:'notes',label:'Notas',type:'textarea',full:true}];
 const filter=()=>{const q=normalizeName($('#institutionSearch').value),show=$('#institutionInactive').checked;let n=0;document.querySelectorAll('[data-institution-row]').forEach(tr=>{const ok=(!q||tr.dataset.search.includes(q))&&(show||tr.dataset.active==='1');tr.hidden=!ok;if(ok)n++;});$('#institutionCount').textContent=`Mostrando ${n} de ${all.length} institución(es).`;};
 $('#institutionSearch').oninput=filter;$('#institutionInactive').onchange=filter;filter();
 $('#newInstitution').onclick=()=>openForm('Nueva institución',fields,{id:crypto.randomUUID(),active:true,created_at:new Date().toISOString()},r=>dirty(T('institutions'),r));$('#refreshInstitutions').onclick=render;
