 const filter=()=>{const q=normalizeName($('#ensembleSearch').value),iid=$('#ensembleInstitution').value,show=$('#ensembleInactive').checked;let n=0;document.querySelectorAll('[data-ensemble-row]').forEach(tr=>{const ok=(!q||tr.dataset.search.includes(q))&&(!iid||tr.dataset.inst===iid)&&(show||tr.dataset.active==='1');tr.hidden=!ok;if(ok)n++;});$('#ensembleCount').textContent=`Mostrando ${n} de ${visible.length} agrupación(es).`;};
