 $('#levelScope').onchange=async e=>{await setSetting('levelsScope',e.target.value);render()};$('#refreshLevels').onclick=render;document.querySelectorAll('[data-level-up]').forEach(b=>b.onclick=()=>reorderRows('academic_levels',arr,b.dataset.levelUp,-1));document.querySelectorAll('[data-level-down]').forEach(b=>b.onclick=()=>reorderRows('academic_levels',arr,b.dataset.levelDown,1));document.querySelectorAll('[data-level-toggle]').forEach(b=>b.onclick=()=>toggleActive('academic_levels',arr.find(x=>x.id===b.dataset.levelToggle)));document.querySelectorAll('[data-level-edit]').forEach(b=>b.onclick=()=>openForm('Editar nivel o grupo',[{name:'name',label:'Nombre',required:true},{name:'active',label:'Activo',type:'checkbox'}],arr.find(x=>x.id===b.dataset.levelEdit),r=>dirty(T('academic_levels'),r)));document.querySelectorAll('[data-level-del]').forEach(b=>b.onclick=()=>confirmDelete(T('academic_levels'),arr.find(x=>x.id===b.dataset.levelDel),'nivel o grupo'));
