 const mode=await setting('membersSort','Apellido'),showInactive=await setting('membersShowInactive',true),arr=all.filter(x=>x.ensemble_id===working&&(showInactive||x.active!==false)).sort(memberSortComparator(mode,cats,levels));
 const catMap=new Map(cats.map(x=>[x.id,x])),levelMap=new Map(levels.map(x=>[x.id,x])),contactByMember=new Map(contacts.map(x=>[x.member_id,x]));
 setPage('Integrantes','Ficha, clasificación y datos de contacto',sortControl('membersSort',mode)+'<button id="importMembers" class="secondary" '+(working?'':'disabled')+'>Importar</button><button id="newMember" '+(working?'':'disabled')+'>Nuevo</button>');
 content.innerHTML=`<div class="panel"><div class="toolbar"><label class="inline-field">Agrupación <select id="membersEnsemble">${ens.map(e=>opt(e.id,e.name,working)).join('')}</select></label><button id="membersUseContext" class="secondary" ${ctx.ensemble?'':'disabled'}>Usar contexto</button><label class="inline-check"><input id="membersInactive" type="checkbox" ${showInactive?'checked':''}> Mostrar inactivos</label></div><div class="table-wrap"><table><thead><tr><th>N.º</th><th>Nombre</th><th>Sección</th><th>Nivel o grupo</th><th>Teléfono</th><th>Correo</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>${arr.map((m,i)=>{const c=contactByMember.get(m.id)||{};return`<tr><td>${i+1}</td><td><strong>${esc(fullName(m))}</strong></td><td>${esc(catMap.get(m.category_id)?.name||'-')}</td><td>${esc(levelMap.get(m.level_id)?.name||'-')}</td><td>${esc(c.phone||m.phone||'-')}</td><td>${esc(c.email||m.email||'-')}</td><td>${m.active!==false?'<span class="pill">Activo</span>':'Inactivo'}</td><td><div class="actions"><button class="small secondary" data-member-toggle="${m.id}">${m.active!==false?'Desactivar':'Activar'}</button><button class="small secondary" data-member-edit="${m.id}">Editar</button><button class="small danger" data-member-del="${m.id}">Eliminar</button></div></td></tr>`}).join('')||'<tr><td colspan="8" class="empty">No hay integrantes visibles.</td></tr>'}</tbody></table></div><p class="muted">Mostrando ${arr.length} integrante(s).</p></div>`;
 $('#membersSort').onchange=async e=>{await setSetting('membersSort',e.target.value);render()};$('#membersEnsemble').onchange=async e=>{await setSetting('membersEnsemble',e.target.value);render()};$('#membersUseContext').onclick=async()=>{if(ctx.ensemble){await setSetting('membersEnsemble',ctx.ensemble);render()}};$('#membersInactive').onchange=async e=>{await setSetting('membersShowInactive',e.target.checked);render()};
 const memberFields=(member={},contact={})=>[{name:'first_name',label:'Nombre',required:true},{name:'last_name',label:'Apellidos'},{name:'birth_date',label:'Fecha nacimiento (DD-MM o fecha completa)'},{name:'join_date',label:'Fecha ingreso'},{name:'leave_date',label:'Fecha baja'},{name:'category_id',label:'Sección',type:'select',nullable:true,options:()=>cats.filter(x=>x.ensemble_id===working).sort((a,b)=>Number(a.display_order||0)-Number(b.display_order||0)).map(x=>({value:x.id,label:x.name}))},{name:'level_id',label:'Nivel o grupo',type:'select',nullable:true,options:()=>{const en=ens.find(x=>x.id===working);return levels.filter(x=>x.ensemble_id===working||x.institution_id===en?.institution_id).sort((a,b)=>Number(a.display_order||0)-Number(b.display_order||0)).map(x=>({value:x.id,label:`${x.name}${x.institution_id?' (institución)':' (agrupación)'}`}))}},{name:'phone',label:'Teléfono'},{name:'email',label:'Correo',type:'email'},{name:'guardian_name',label:'Representante'},{name:'guardian_phone',label:'Tel. representante'},{name:'emergency_contact',label:'Emergencia'},{name:'medical_note',label:'Nota médica'},{name:'general_notes',label:'Notas generales',type:'textarea',full:true},{name:'active',label:'Activo',type:'checkbox',default:true}];
 const openMember=(member=null)=>{const contact=member?contactByMember.get(member.id)||{}:{},merged={...(member||{id:crypto.randomUUID(),ensemble_id:working,active:true,created_at:new Date().toISOString()}),phone:contact.phone??member?.phone??'',email:contact.email??member?.email??'',guardian_name:contact.guardian_name||'',guardian_phone:contact.guardian_phone||'',emergency_contact:contact.emergency_contact||'',medical_note:contact.medical_note||''};openForm(member?'Editar integrante':'Nuevo integrante',memberFields(member,contact),merged,async r=>{const contactId=contact.id||crypto.randomUUID(),memberRow={...r,ensemble_id:working,phone:r.phone||'',email:r.email||'',medical_info:r.medical_note||''};delete memberRow.guardian_name;delete memberRow.guardian_phone;delete memberRow.emergency_contact;delete memberRow.medical_note;await dirty(T('members'),memberRow);await dirty(T('member_contacts'),{...contact,id:contactId,member_id:memberRow.id,contact_type:contact.contact_type||'contact',name:contact.name||'',relationship:contact.relationship||'',phone:r.phone||'',email:r.email||'',guardian_name:r.guardian_name||'',guardian_phone:r.guardian_phone||'',emergency_contact:r.emergency_contact||'',medical_note:r.medical_note||'',display_order:contact.display_order||0,created_at:contact.created_at||new Date().toISOString()});});};
