  for(const e of entries){if(!entryMap.has(e.date))entryMap.set(e.date,[]);entryMap.get(e.date).push(e)}
  const isoUTC=d=>`${d.getUTCFullYear()}-${String(d.getUTCMonth()+1).padStart(2,'0')}-${String(d.getUTCDate()).padStart(2,'0')}`;
  const first=new Date(Date.UTC(y,m-1,1)),last=new Date(Date.UTC(y,m,0)),startDate=new Date(first),endDate=new Date(last);
  startDate.setUTCDate(startDate.getUTCDate()-((startDate.getUTCDay()+6)%7));endDate.setUTCDate(endDate.getUTCDate()+(6-((endDate.getUTCDay()+6)%7)));
