  const saveYm=async(ny,nm)=>{while(nm<1){nm+=12;ny--}while(nm>12){nm-=12;ny++}await setSetting('calendarYear',ny);await setSetting('calendarMonth',nm);render()};
  $('#calendarConcert').onchange=async e=>{const id=e.target.value||null;await setSetting('selectedPlannedConcert',id);const nc=allConcerts.find(x=>x.id===id);if(nc){await setSetting('calendarYear',Number(nc.concert_date.slice(0,4)));await setSetting('calendarMonth',Number(nc.concert_date.slice(5,7)));}render()};
